(7296362, 1137574, 96751, '<td valign="top">I love this type of shot. Probably would have liked it better in b/w</td>', 'I love this type of shot. Probably would have liked it better in b/w', '2014-12-28 21:07:18.000000', NULL, 1),
(7296364, 1137549, 135629, '<td valign="top">Great Lik style shot. I gave this a 9, the color is great and it''s perfectly suited for the challenge. Very slightly soft focus throughout, where a Lik would be razor sharp from the shore to clouds in the distance. Great job! I think this would be a really nice print on a metallic paper, as Lik does.</td>', 'Great Lik style shot. I gave this a 9, the color is great and it''s perfectly suited for the challenge. Very slightly soft focus throughout, where a Lik would be razor sharp from the shore to clouds in the distance. Great job! I think this would be a really nice print on a metallic paper, as Lik does.', '2014-12-28 21:09:58.000000', NULL, 1),
(7296365, 1137422, 135629, '<td valign="top">I gave this an 8 because it''s a grand scene, and the tones are good. Would have been higher if a bit longer vertical or horizontal portrait (like Lik is most common for). Also, I know they are there - so composition you are dealing with what you can, but if the wood structures and edge of a dock were not in the lower left corner all distraction would be gone and the bridge would just POW... right in the face.</td>', 'I gave this an 8 because it''s a grand scene, and the tones are good. Would have been higher if a bit longer vertical or horizontal portrait (like Lik is most common for). Also, I know they are there - so composition you are dealing with what you can, but if the wood structures and edge of a dock were not in the lower left corner all distraction would be gone and the bridge would just POW... right in the face.', '2014-12-28 21:10:01.000000', NULL, 1),
(7296370, 1137575, 135629, '<td valign="top">I really like the colors in your image, good luck!</td>', 'I really like the colors in your image, good luck!', '2014-12-28 21:15:53.000000', NULL, 1),
(7296372, 1137566, 135629, '<td valign="top">Neat subject! Well done.</td>', 'Neat subject! Well done.', '2014-12-28 21:19:38.000000', NULL, 1),
(7296373, 1137614, 135629, '<td valign="top">Love the clarity from edge to edge. Good tones, and colors throughout. Great Job!</td>', 'Love the clarity from edge to edge. Good tones, and colors throughout. Great Job!', '2014-12-28 21:21:57.000000', NULL, 1),
(7296374, 1137574, 135629, '<td valign="top">This is a beautiful scene, and would probably make a really nice HD panoramic print, just like Lik does :)</td>', 'This is a beautiful scene, and would probably make a really nice HD panoramic print, just like Lik does :)', '2014-12-28 21:22:40.000000', NULL, 1),
(7296376, 1137301, 96751, '<td valign="top">I love this!!  What a wild image. And yet, delicate and well-balanced</td>', 'I love this!!  What a wild image. And yet, delicate and well-balanced', '2014-12-28 21:25:00.000000', NULL, 1),
(7296377, 1137526, 96751, '<td valign="top">Wonderful symmetry</td>', 'Wonderful symmetry', '2014-12-28 21:26:18.000000', NULL, 1),
