(7296419, 1137604, 135629, '<td valign="top">Gotta love that foggy effect from the water movement against the stones. Great colors in the sky, and great sharpness edge to edge.</td>', 'Gotta love that foggy effect from the water movement against the stones. Great colors in the sky, and great sharpness edge to edge.', '2014-12-28 23:50:59.000000', NULL, 1),
