(7296523, 1137565, 124982, '<td valign="top">Great to see an image not processed to within an inch of its life. Very clean and natural and most appealing.</td>', 'Great to see an image not processed to within an inch of its life. Very clean and natural and most appealing.', '2014-12-29 07:51:52.000000', NULL, 0),
(7296524, 1137633, 12611, '<td valign="top">The foreground is terrific here. have no regrets.</td>', 'The foreground is terrific here. have no regrets.', '2014-12-29 07:55:54.000000', NULL, 0),
(7296528, 1137565, 135629, '<td valign="top">Single 13 second exposure, first real shoot with my new Tokina 16-28mm f/2.8 FX PRO lens, and I love this lens. Shot this on a tripod, with a remote trigger. Also used my Nikon SB-700 to fire a touch of light out underneath the pier to balance with the long exposure of the sky, etc.</td>', 'Single 13 second exposure, first real shoot with my new Tokina 16-28mm f/2.8 FX PRO lens, and I love this lens. Shot this on a tripod, with a remote trigger. Also used my Nikon SB-700 to fire a touch of light out underneath the pier to balance with the long exposure of the sky, etc.', '2014-12-29 08:06:02.000000', NULL, 0),
(7296533, 1137604, 124982, '<td valign="top">Really like the subdued colors and tones on this, Mark. So easy to over saturate these kind of shots.</td>', 'Really like the subdued colors and tones on this, Mark. So easy to over saturate these kind of shots.', '2014-12-29 08:40:14.000000', NULL, 0),
(7296534, 1137566, 124982, '<td valign="top">Exceedingly peaceful and meditative image. Minimal and simplistic and quite perfect.</td>', 'Exceedingly peaceful and meditative image. Minimal and simplistic and quite perfect.', '2014-12-29 08:41:42.000000', NULL, 0),
(7296536, 1137301, 50864, '<td valign="top">This is very interesting. I like it a lot. Perfect subject for the processing.</td>', 'This is very interesting. I like it a lot. Perfect subject for the processing.', '2014-12-29 08:53:58.000000', NULL, 0),
(7296537, 1137633, 50864, '<td valign="top">This is lovely, especially the foreground. I bet it would really be amazing blown up.</td>', 'This is lovely, especially the foreground. I bet it would really be amazing blown up.', '2014-12-29 09:02:57.000000', NULL, 0),
(7296538, 1137588, 50864, '<td valign="top">Yes, you didn''t tell us how many months you waited for this perfect moon shot and how many hours you sat crouched in the dark waiting, etc, etc. Not easy to get 24th out of 37 with seven 10''s. Have to fav this.</td>', 'Yes, you didn''t tell us how many months you waited for this perfect moon shot and how many hours you sat crouched in the dark waiting, etc, etc. Not easy to get 24th out of 37 with seven 10''s. Have to fav this.', '2014-12-29 09:12:49.000000', NULL, 0),
